<script setup lang="ts">import {computed} from 'vue';import type {EChartsOption} from 'echarts';import BaseChart from '@/components/BaseChart.vue';import ScreenPanel from './ScreenPanel.vue';import type {DashboardCarbon,DashboardEnergy,DashboardMarket} from '@/types';const props=defineProps<{carbon:DashboardCarbon;energy:DashboardEnergy;market:DashboardMarket}>();const carbonChart=computed<EChartsOption>(()=>({xAxis:{type:'category',data:props.carbon.trend.map(x=>x.timestamp)},yAxis:{type:'value'},series:[{type:'line',areaStyle:{},name:'碳排',data:props.carbon.trend.map(x=>x.emission_t)}]}));const energyChart=computed<EChartsOption>(()=>({xAxis:{type:'category',data:props.energy.hourly.slice(-168).map(x=>x.timestamp)},yAxis:{type:'value'},series:[{type:'line',name:'原始负荷',data:props.energy.hourly.slice(-168).map(x=>x.load_base_kwh)},{type:'line',name:'节能后',data:props.energy.hourly.slice(-168).map(x=>x.load_after_saving_kwh)},{type:'line',name:'电网购电',data:props.energy.hourly.slice(-168).map(x=>x.grid_power_kwh)},{type:'line',name:'PV',data:props.energy.hourly.slice(-168).map(x=>x.pv_generation_kwh)},{type:'line',name:'风电',data:props.energy.hourly.slice(-168).map(x=>x.wind_generation_kwh)}]}));const marketChart=computed<EChartsOption>(()=>({xAxis:{type:'category',data:props.market.statistics?.records.map(x=>x.timestamp)||[]},yAxis:{type:'value'},series:[{type:'line',name:'碳价',data:props.market.statistics?.records.map(x=>x.carbon_price_per_t)||[]}]}));</script>
<template><ScreenPanel title="碳排趋势" link="/carbon" :empty="!carbon.trend.length"><BaseChart :option="carbonChart" height="210px"/></ScreenPanel><ScreenPanel title="能源供需趋势" link="/data" :empty="!energy.hourly.length" empty-text="暂无小时仿真数据"><BaseChart :option="energyChart" height="210px"/></ScreenPanel><ScreenPanel title="碳价趋势" link="/carbon-market" :empty="!market.statistics?.record_count" empty-text="暂无碳市场数据"><BaseChart :option="marketChart" height="210px"/></ScreenPanel></template>
